"use client"

import { useState, useEffect } from "react"
import Layout from "../components/Layout"
import StatsCards from "../components/StatsCards"
import RecentActivity from "../components/RecentActivity"
import api from "../services/api"
import DailyEntriesTable from "../components/DailyEntriesTable";

const Dashboard = () => {
  const [stats, setStats] = useState({
    totalParked: 0,
    todayEntries: 0,
    todayExits: 0,
    totalRevenue: 0,
    vehicleTypes: [],
  })
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetchStats()
    fetchDailyEntries()
    const interval = setInterval(() => {
      fetchStats()
      fetchDailyEntries()
    }, 30000) // Refresh every 30 seconds
    return () => clearInterval(interval)
  }, [])

  const fetchStats = async () => {
    try {
      const response = await api.get("/dashboard/stats")
      setStats(prev => ({
        ...prev,
        totalParked: response.data.totalParked,
        todayExits: response.data.todayExits,
        totalRevenue: response.data.totalRevenue,
        vehicleTypes: response.data.vehicleTypes,
        // Do NOT set todayEntries here!
      }))
    } catch (error) {
      console.error("Error fetching stats:", error)
    } finally {
      setLoading(false)
    }
  }

  const fetchDailyEntries = async () => {
    try {
      const response = await api.get("/dashboard/daily-entries")
      if (response.data.success) {
        const today = new Date().toISOString().slice(0, 10)
        const todayEntry = response.data.data.find(row => row.date === today)
        setStats(prev => ({ ...prev, todayEntries: todayEntry ? todayEntry.count : 0 }))
      }
    } catch (error) {
      console.error("Error fetching daily entries:", error)
    }
  }

  return (
    <Layout>
      <div className="space-y-6">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Dashboard</h1>
          <p className="text-gray-600">Overview of your smart parking system</p>
        </div>

        <StatsCards stats={stats} loading={loading} />
        <RecentActivity />
        
        <DailyEntriesTable />
      </div>
    </Layout>
  )
}

export default Dashboard
// Get daily exit counts from exitvehicles
router.get("/daily-exits", authenticateToken, async (req, res) => {
  try {
    const mongooseDb = require("mongoose").connection.db;
    const dailyCounts = await mongooseDb.collection("exitvehicles").aggregate([
      {
        $group: {
          _id: {
            $dateToString: { format: "%Y-%m-%d", date: "$exitTime" }
          },
          count: { $sum: 1 }
        }
      },
      { $sort: { _id: -1 } }
    ]).toArray();
    // Map to { date, count }
    const result = dailyCounts.map(row => ({ date: row._id, count: row.count }));
    res.json({ success: true, data: result });
  } catch (error) {
    res.status(500).json({ success: false, message: "Failed to fetch daily exits", error: error.message });
  }
});
